// GinServerOptions provides options for the Gin server.
type GinServerOptions struct {
	BaseURL      string
	Middlewares  []MiddlewareFunc
	ErrorHandler func(*gin.Context, error, int)
}

// RegisterHandlers creates http.Handler with routing matching OpenAPI spec.
func RegisterHandlers(router gin.IRouter, si ServerInterface) {
	RegisterHandlersWithOptions(router, si, GinServerOptions{})
}

// RegisterHandlersWithOptions creates http.Handler with additional options
func RegisterHandlersWithOptions(router gin.IRouter, si ServerInterface, options GinServerOptions) {
	errorHandler := options.ErrorHandler
	if errorHandler == nil {
		errorHandler = func(c *gin.Context, err error, statusCode int) {
			c.JSON(statusCode, gin.H{"msg": err.Error()})
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandler:       errorHandler,
	}

	router.GET(options.BaseURL+"/admin/audit", wrapper.ListAdminAudit)
	router.GET(options.BaseURL+"/admin/environments", wrapper.ListAdminEnvironments)
	router.POST(options.BaseURL+"/admin/environments/:name/release", wrapper.ReleaseAdminEnvironment)
	router.GET(options.BaseURL+"/admin/runnable-actions", wrapper.ListAdminRunnableActions)
	router.GET(options.BaseURL+"/admin/runnable-reaps", wrapper.ListAdminRunnableReaps)
	router.GET(options.BaseURL+"/admin/system", wrapper.GetAdminSystem)
	router.GET(options.BaseURL+"/admin/users", wrapper.ListAdminUsers)
	router.POST(options.BaseURL+"/admin/users/:id/totp-reset", wrapper.ResetAdminUserTOTP)
	router.POST(options.BaseURL+"/auth/login", wrapper.Login)
	router.POST(options.BaseURL+"/auth/register", wrapper.Register)
	router.POST(options.BaseURL+"/authoring/scenarios/:id/deprecate", wrapper.DeprecateAuthoringScenario)
	router.POST(options.BaseURL+"/authoring/scenarios/:id/revisions", wrapper.CreateAuthoringScenarioRevision)
	router.POST(options.BaseURL+"/authoring/sessions", wrapper.CreateAuthoringSession)
	router.GET(options.BaseURL+"/authoring/sessions/current", wrapper.GetCurrentAuthoringSession)
	router.GET(options.BaseURL+"/authoring/sessions/:id", wrapper.GetAuthoringSession)
	router.POST(options.BaseURL+"/authoring/sessions/:id/messages", wrapper.SendAuthoringMessage)
	router.GET(options.BaseURL+"/documentation/asset", wrapper.GetDocumentationAsset)
	router.GET(options.BaseURL+"/documentation/page", wrapper.GetDocumentationPage)
	router.GET(options.BaseURL+"/documentation/tree", wrapper.GetDocumentationTree)
	router.POST(options.BaseURL+"/generator/plans", wrapper.SetGenerationPlan)
	router.GET(options.BaseURL+"/generator/workflows", wrapper.ListActiveGenerations)
	router.POST(options.BaseURL+"/generator/workflows", wrapper.ConfirmGeneration)
	router.GET(options.BaseURL+"/generator/workflows/:workflow_id", wrapper.GetGeneration)
	router.POST(options.BaseURL+"/generator/workflows/:workflow_id/cancel", wrapper.CancelGeneration)
	router.POST(options.BaseURL+"/generator/workflows/:workflow_id/candidate", wrapper.SubmitGeneratorCandidate)
	router.POST(options.BaseURL+"/generator/workflows/:workflow_id/content/changes", wrapper.RequestGeneratorContentChanges)
	router.POST(options.BaseURL+"/generator/workflows/:workflow_id/content/confirm", wrapper.ConfirmGeneratorContent)
	router.GET(options.BaseURL+"/generator/workflows/:workflow_id/review-bundle", wrapper.GetGeneratorReviewBundle)
	router.POST(options.BaseURL+"/generator/workflows/:workflow_id/workspace/commands", wrapper.RunGeneratorWorkspaceCommand)
	router.GET(options.BaseURL+"/generator/workflows/:workflow_id/workspace/file", wrapper.ReadGeneratorWorkspaceFile)
	router.GET(options.BaseURL+"/generator/workflows/:workflow_id/workspace/files", wrapper.ListGeneratorWorkspaceFiles)
	router.PUT(options.BaseURL+"/generator/workflows/:workflow_id/workspace/files", wrapper.WriteGeneratorWorkspaceFile)
	router.POST(options.BaseURL+"/generator/workflows/:workflow_id/workspace/turn", wrapper.StartGeneratorWorkspaceTurn)
	router.POST(options.BaseURL+"/generator/workflows/:workflow_id/workspace/turn/end", wrapper.EndGeneratorWorkspaceTurn)
	router.GET(options.BaseURL+"/me/space", wrapper.GetMySpace)
	router.GET(options.BaseURL+"/me/space/learning", wrapper.GetMySpaceLearning)
	router.GET(options.BaseURL+"/operations/scenarios", wrapper.ListScenarios)
	router.GET(options.BaseURL+"/operations/scenarios/:id/assistant", wrapper.GetScenarioAssistant)
	router.POST(options.BaseURL+"/operations/scenarios/:id/assistant/messages", wrapper.SendScenarioAssistantMessage)
	router.GET(options.BaseURL+"/operations/scenarios/:id/content", wrapper.GetScenarioContent)
	router.GET(options.BaseURL+"/operations/scenarios/:id/progress", wrapper.GetScenarioProgress)
	router.POST(options.BaseURL+"/operations/scenarios/:id/reset", wrapper.ResetScenario)
	router.POST(options.BaseURL+"/operations/scenarios/:id/start", wrapper.StartScenario)
	router.POST(options.BaseURL+"/operations/scenarios/:id/stop", wrapper.StopScenario)
	router.POST(options.BaseURL+"/operations/scenarios/:id/terminal-ticket", wrapper.CreateTerminalTicket)
	router.DELETE(options.BaseURL+"/operations/scenarios/:id/terminals/:window", wrapper.CloseTerminalWindow)
	router.DELETE(options.BaseURL+"/playground", wrapper.ClosePlayground)
	router.GET(options.BaseURL+"/playground", wrapper.GetPlayground)
	router.POST(options.BaseURL+"/playground", wrapper.CreatePlayground)
	router.POST(options.BaseURL+"/playground/reset", wrapper.ResetPlayground)
	router.POST(options.BaseURL+"/playground/terminal-ticket", wrapper.CreatePlaygroundTerminalTicket)
}

